<script lang="ts">
 import AdventureContent from '$lib/components/AdventureContent.svelte';import { BESTIARY } from '$lib/rules/bestiary';import { getCombat,saveCombat,createEmptyCombat } from '$lib/sync/combat';import { getCurrentRoom,findRoomByCode,getRoomCombatState,saveRoomCombatState } from '$lib/engine/rooms';import { adventureEnemiesToCombat,freshReadyCharacter,type AdventureEnemy } from '$lib/engine/customAdventures';import { saveCharacter } from '$lib/db/characters';import { goto } from '$app/navigation';import type { PageData } from './$types';
 let {data}:{data:PageData}=$props();const record=$derived(data.record);let busy=$state(false),message=$state('');
 async function addEnemies(groups:AdventureEnemy[]){if(busy||!groups.length)return;busy=true;message='';try{const code=getCurrentRoom();const room=code?await findRoomByCode(code):null;if(code&&!room)throw new Error('Игровая комната не найдена.');const current=room?await getRoomCombatState(room.id):getCombat();const next=adventureEnemiesToCombat(current??createEmptyCombat(),groups);if(room)await saveRoomCombatState(room.id,next);saveCombat(next);message=`В трекер добавлено врагов: ${groups.reduce((sum,e)=>sum+e.count,0)}. Текущий ход сохранён.`;}catch(cause){message=(cause as Error).message;}finally{busy=false;}}
 async function takeHero(index:number){if(busy)return;busy=true;message='';try{const copy=freshReadyCharacter(record.readyCharacters[index]);await saveCharacter(copy);await goto(`/char/${copy.id}`);}catch(cause){message=(cause as Error).message;}finally{busy=false;}}
 function download(){const url=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=`adventure-${record.id}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
</script>
{#snippet extras()}
<div class="extras"><div class="actions"><a href={`/adventures/custom/${record.id}/edit`}>Редактировать приключение</a><button onclick={download}>Скачать копию JSON</button></div><p>Ваше приключение сохранено на этом устройстве в текущем аккаунте.</p>
 {#if record.maps.length>1}<details><summary>Карты приключения · {record.maps.length}</summary>{#each record.maps as map}<figure><img src={map.src} alt={map.name}/><figcaption>{map.caption}</figcaption></figure>{/each}</details>{/if}
 {#if record.readyCharacters.length}<section><h2>Готовые персонажи для игры</h2>{#each record.readyCharacters as character,index}<div class="card"><strong>{character.name} · ур. {character.level}</strong><p>Независимая копия героя попадёт в ваши персонажи.</p><button disabled={busy} onclick={()=>takeHero(index)}>Играть за {character.name}</button></div>{/each}</section>{/if}
 {#if record.enemies.length}<section><h2>Враги приключения</h2>{#each record.enemies as enemy}{@const monster=BESTIARY.find(m=>m.id===enemy.monsterId)}<div class="card"><h3>{monster?.name??enemy.monsterId} × {enemy.count} · ур. {enemy.level}</h3><p>{record.adventure.scenes.find(s=>s.id===enemy.sceneId)?.title??'Любая сцена'} · {enemy.notes}</p><a href={`/gm/bestiary?monster=${enemy.monsterId}`}>Открыть карточку</a><button disabled={busy} onclick={()=>addEnemies([enemy])}>Добавить группу в боевой трекер</button></div>{/each}<button disabled={busy} onclick={()=>addEnemies(record.enemies)}>Добавить всех врагов в трекер</button><a href="/gm/combat">Открыть боевой трекер →</a></section>{/if}
 {#if message}<p role="status">{message}</p>{/if}
</div>
{/snippet}
{#key record.id}<AdventureContent adventure={record.adventure} {extras}/>{/key}
<style>.extras{margin:20px 0;padding:0}.extras section,.extras details{border:1px solid #aab9ac;border-radius:10px;padding:18px;margin-top:16px;background:#fffef8}.actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.card{border-top:1px solid #d5daca;padding:12px 0}.card h3{font-size:1.2rem}h2{font-size:1.5rem}button{padding:9px 12px;margin:4px;border:1px solid #476b54;border-radius:7px;background:#e9eddf;color:#173d30}button:disabled{opacity:.5}a{text-decoration:underline}.extras img{max-width:100%;max-height:600px;object-fit:contain}@media(max-width:600px){.extras{padding:0 16px}}</style>
